/* Operational prototype: synchronized browser workspaces, scheduling, setup and notification outbox. */
const operationsKey='hairflix-demo-v1';
function normalizeOperationMessages(value){for(const thread of value.extras?.conversations||[])for(const m of thread.messages||[])if(!m.id)m.id='message-'+JSON.stringify([thread.id,m.at,m.role,m.name,m.body,m.appointment]);return value;}
normalizeOperationMessages({extras});
const operationSnapshot=()=>structuredClone({bookings,checked,messages,extras});
let operationsBase=operationSnapshot(),operationsReceiving=false;
function defaultShopHours(location,day){return location==='university'?(day===1||day===2?[480,1320]:day===0||day===6?[450,1260]:[450,1320]):[540,1080];}
function bookingHours(barber,date,location=extras.location){const day=dateObj(date).getDay(),staff=extras.staffHours?.[barber]?.[day],shop=extras.shopHours?.[location]?.[day];if(staff===null||shop===null)return null;const ranges=[shop||defaultShopHours(location,day),staff||[0,1440]];return [Math.max(...ranges.map(x=>x[0])),Math.min(...ranges.map(x=>x[1]))];}
function schedulingError(barber,date,time,duration,ignoreId,location=extras.location){if(extras.staffBookingEnabled?.[barber]===false)return 'This barber is not accepting bookings.';return HFOperations.scheduleError({barber,date,time,duration,ignoreId,bookings,blocks:extras.blocks,hours:bookingHours(barber,date,location)});}
conflict=function(barber,date,start,duration){return !!schedulingError(barber,date,agendaTime(start),duration);};
sampleBusy=function(time,duration){return !!schedulingError(state.barber,state.date,time,duration,state.editing);};
const operationalConfirm=confirmBooking;confirmBooking=function(){pullOperations(false);const error=schedulingError(state.barber,state.date,state.time,S().min,state.editing);if(error){state.time='';state.step=2;render();toast(error);return;}operationalConfirm();};
const originalAgendaValidation=agendaValidation;agendaValidation=function(b,date,time){const base=originalAgendaValidation(b,date,time);return base||schedulingError(b.barber,date,time,bookingDuration(b),b.id,b.location);};
function reconcileOperationValue(target,source){
 if(Array.isArray(source)){if(!Array.isArray(target))return structuredClone(source);const keyed=new Map(target.filter(x=>x&&typeof x==='object'&&x.id).map(x=>[x.id,x]));const next=source.map((value,i)=>reconcileOperationValue(value&&typeof value==='object'&&value.id?keyed.get(value.id):target[i],value));target.splice(0,target.length,...next);return target;}
 if(source&&typeof source==='object'){if(!target||typeof target!=='object'||Array.isArray(target))return structuredClone(source);for(const key of Object.keys(target))if(!(key in source))delete target[key];for(const [key,value] of Object.entries(source))target[key]=reconcileOperationValue(target[key],value);return target;}
 return source;
}
function applyOperations(value){
 if(Array.isArray(value.bookings))bookings=reconcileOperationValue(bookings,value.bookings);
 if(value.checked)checked=reconcileOperationValue(checked,value.checked);if(Array.isArray(value.messages))messages=reconcileOperationValue(messages,value.messages);if(value.extras)reconcileOperationValue(extras,value.extras);
 for(const b of barbers){const profile=extras.barberProfiles?.[b.id];if(profile)Object.assign(b,profile);b.short=b.name.split(' ')[0];}
 for(const [id,shop] of Object.entries(extras.setupLocations||{})){shops[id]={...shops[id],...shop};if(shop.address)shopAddresses[id]=shop.address;}
 if(Array.isArray(extras.catalog))for(const item of extras.catalog){const target=services.find(s=>s.id===item.id);if(target)Object.assign(target,item);else services.push(item);}
 const visit=bookings.find(b=>b.id===state.visitId);if(isStaff()&&visit?.settlement?.status==='paid'&&['pTicket','pFinalize','pAppointment'].includes(state.view))state.view='staffReceipt';
}
function notificationPrefs(){return {sms:false,confirmations:true,reschedules:true,cancellations:true,reminders:extras.profile.reminders!==false,...extras.notificationPrefs};}
function recordAppointmentEvents(previous){
 extras.appointmentActivity=extras.appointmentActivity||[];extras.textOutbox=extras.textOutbox||[];
 const before=new Map((previous.bookings||[]).map(b=>[b.id,b]));
 for(const b of bookings){const old=before.get(b.id);let type=!old?'confirmations':b.status==='cancelled'&&old.status!=='cancelled'?'cancellations':b.date!==old.date||b.time!==old.time?'reschedules':b.settlement?.status==='paid'&&old.settlement?.status!=='paid'?'payment':null;
 if(!type||b.calendarExample||(!old&&b.id.startsWith('demo')))continue;
 if(type==='reschedules'&&b.previousSlots?.at(-1)?.notified===false)continue;
 appendAppointmentEvent(b,type,`${type}:${b.id}:${b.date}:${b.time}:${type==='cancellations'?b.cancelledAt||'cancelled':''}`);
 }
}
function appendAppointmentEvent(b,type,id){
 if(extras.appointmentActivity.some(x=>x.id===id))return;
 const labels={confirmations:b.status==='pending_payment'?'Booking awaiting payment':'Appointment confirmed',reschedules:'Appointment rescheduled',cancellations:'Appointment cancelled',reminders:'Your appointment is coming up',payment:'Payment recorded'};
 const body=`${labels[type]}: ${barbers.find(x=>x.id===b.barber)?.name||'Your barber'}, ${pretty(b.date)} at ${b.time}. ${bookingName(b)}${type==='payment'?' · '+cents(b.settlement.amountCents):''}.`;
 const event={id,bookingId:b.id,barber:b.barber,client:b.client,type,title:labels[type],body,at:Date.now()};extras.appointmentActivity.push(event);
 const own=b.client==='John B.',prefs=own?notificationPrefs():b.notificationPrefs||{sms:false};
 const phone=own?extras.profile.phone:b.phone;
 if(type!=='payment'&&prefs.sms&&prefs[type]!==false&&phone?.replace(/\D/g,'').length>=10)extras.textOutbox.push({...event,phone,status:'not_connected'});
 extras.appointmentActivity=extras.appointmentActivity.slice(-300);extras.textOutbox=extras.textOutbox.slice(-300);
}
function reconcileOutbox(){for(const item of extras.textOutbox||[]){const b=bookings.find(b=>b.id===item.bookingId);if(!b||item.type!=='cancellations'&&(b.status==='cancelled'||!item.id.includes(`:${b.date}:${b.time}:`))||b.client==='John B.'&&(!notificationPrefs().sms||notificationPrefs()[item.type]===false))item.status='suppressed';}}
function pullOperations(redraw=true){try{const raw=localStorage.getItem(operationsKey);if(!raw)return;const remote=normalizeOperationMessages(JSON.parse(raw));if(JSON.stringify(remote)===JSON.stringify(operationsBase))return;const merged=HFOperations.merge(operationsBase,operationSnapshot(),remote);operationsReceiving=true;applyOperations(merged);operationsBase=structuredClone(remote);operationsReceiving=false;if(redraw)renderPreservingInputs();}catch{}finally{operationsReceiving=false;}}
function renderPreservingInputs(){
 const active=document.activeElement,selector=active?.name?`[name="${CSS.escape(active.name)}"]`:active?.id?'#'+CSS.escape(active.id):null;
 const fields=[...document.querySelectorAll('#main input,#main textarea,#main select')].map(el=>({form:el.form?.id,name:el.name,value:el.value,checked:el.checked}));
 const selection=active&&'selectionStart'in active?[active.selectionStart,active.selectionEnd]:null,y=scrollY;
 render();for(const field of fields){if(!field.form||!field.name)continue;document.querySelectorAll(`#${CSS.escape(field.form)} [name="${CSS.escape(field.name)}"]`).forEach(el=>{if(el.type==='checkbox'||el.type==='radio'){if(el.value===field.value)el.checked=field.checked;}else if(el.type!=='file')el.value=field.value;});}
 if(selector){const target=document.querySelector('#main '+selector);target?.focus({preventScroll:true});if(selection&&target?.setSelectionRange&&(['text','tel','search','url','password'].includes(target.type)||target.tagName==='TEXTAREA'))try{target.setSelectionRange(...selection);}catch{}}
 window.scrollTo(0,y);
}
save=function(){
 if(operationsReceiving)return;
 try{normalizeOperationMessages({extras});const raw=localStorage.getItem(operationsKey),remote=raw?normalizeOperationMessages(JSON.parse(raw)):null;if(remote)applyOperations(HFOperations.merge(operationsBase,operationSnapshot(),remote));recordAppointmentEvents(operationsBase);reconcileOutbox();localStorage.setItem(operationsKey,JSON.stringify({bookings,checked,messages,extras}));operationsBase=operationSnapshot();}catch{toast('Changes could not be saved. Free browser storage and try again.');}
};
window.addEventListener('storage',e=>{if(e.key===operationsKey)pullOperations();});
window.addEventListener('focus',()=>pullOperations());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pullOperations();});
// Web Locks serialize booking mutations across same-origin tabs; validation runs after acquiring the lock.
const operationsReplays=new WeakSet();
window.addEventListener('click',e=>{
 const target=e.target.closest('button');if(!target||operationsReplays.has(e)||!target.matches('[data-action=confirm],[data-agenda-confirm],[data-confirm-cancel]'))return;
 if(!navigator.locks){pullOperations(false);return;}e.preventDefault();e.stopImmediatePropagation();navigator.locks.request('hairflix-operations',()=>{pullOperations(false);if(!target.isConnected)return;const replay=new MouseEvent('click',{bubbles:true,cancelable:true,view:window});operationsReplays.add(replay);target.dispatchEvent(replay);}).catch(()=>toast('Could not save this change. Please try again.'));
},true);
window.addEventListener('submit',e=>{if(operationsReplays.has(e))return;if(!navigator.locks){pullOperations(false);return;}e.preventDefault();e.stopImmediatePropagation();const form=e.target;navigator.locks.request('hairflix-operations',()=>{pullOperations(false);if(!form.isConnected)return;const replay=new Event('submit',{bubbles:true,cancelable:true});operationsReplays.add(replay);form.dispatchEvent(replay);}).catch(()=>toast('Could not save this change. Please try again.'));},true);
function refreshAppointmentReminders(){if(document.hidden)return;pullOperations(false);extras.appointmentActivity=extras.appointmentActivity||[];extras.textOutbox=extras.textOutbox||[];const before=extras.appointmentActivity.length;for(const b of bookings){if(b.calendarExample||!['confirmed','pending_payment'].includes(b.status))continue;const remaining=HFAppRules.appointmentAt(b)-Date.now();if(remaining>0&&remaining<=24*3600000)appendAppointmentEvent(b,'reminders',`reminders:${b.id}:${b.date}:${b.time}:`);}if(before!==extras.appointmentActivity.length)save();}
setInterval(refreshAppointmentReminders,30000);
function notificationPreferencesPage(){const p=notificationPrefs();return `${head('Your appointment updates.','Choose how you stay in the loop.')}<form id="notification-preferences-form" class="panel ops-form"><label class="field">Mobile number<input type="tel" name="phone" autocomplete="tel" inputmode="tel" maxlength="24" value="${esc(extras.profile.phone||'')}" placeholder="(555) 123-4567"></label><label class="check-row"><input name="sms" type="checkbox" ${p.sms?'checked':''}> Send me appointment texts</label><p class="muted">Appointment messages only. Message and data rates may apply. Text delivery will be available when messaging is connected.</p>${[['confirmations','Booking confirmations'],['reminders','Reminder before my visit'],['reschedules','Time and date changes'],['cancellations','Cancellations']].map(([id,label])=>`<label class="ops-preference"><span>${label}</span><input name="${id}" type="checkbox" ${p[id]?'checked':''}></label>`).join('')}<p class="ops-error" role="alert"></p><button class="btn full">Save preferences</button></form>`;}
notificationsPage=function(){const activity=(extras.appointmentActivity||[]).filter(n=>state.role==='Owner HQ'||(state.role==='Barber Pro'?n.barber===activeBarberId():n.client==='John B.')).slice().reverse();return `${head('Your updates.','Appointments and payments, in one place.',state.role==='Customer'?'<button class="btn secondary small" data-view="notificationPreferences">Preferences</button>':'')}<section class="panel">${activity.length?activity.map(n=>`<button class="notification-row" data-ops-visit="${esc(n.bookingId)}">${icon(n.type==='payment'?'card':'bell')}<div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${new Date(n.at).toLocaleString()}</small></div>${icon('chevron')}</button>`).join(''):'<p class="muted">Appointment changes and payment records will appear here.</p>'}</section>${isStaff()?`<section class="panel"><h2>Appointment texts</h2><p class="muted">Delivery service not connected. These messages have not been sent. Reminders are prepared while the app is open.</p>${(extras.textOutbox||[]).filter(n=>state.role==='Owner HQ'||n.barber===activeBarberId()).slice(-15).reverse().map(n=>`<div class="ops-outbox"><strong>${esc(n.client)} · ${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${n.status==='suppressed'?'Suppressed · changed appointment or preferences':'Not sent · text delivery not connected'}</small></div>`).join('')||'<p class="muted">No appointment texts prepared yet.</p>'}</section>`:''}`;};
function ownerSetupDraft(){if(!extras.ownerSetupDraft){const location=extras.location||'scottsdale';extras.ownerSetupDraft={location,name:shops[location]?.name||'',address:shopAddresses[location]||'',team:barbers.map(b=>({id:b.id,name:b.name,enabled:true})),menus:structuredClone(extras.barberMenus),hours:structuredClone(extras.shopHours?.[location]||Array.from({length:7},(_,i)=>defaultShopHours(location,i))),terms:structuredClone(extras.chairTerms)};}return extras.ownerSetupDraft;}
const setupStepLabels=['Location','Your people','Services','Hours','Agreements','Review'];
function setupInput(label,name,value,type='text',attrs=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
function ownerSetupPage(){if(state.role!=='Owner HQ')return head('Owner access required.','');const draft=ownerSetupDraft(),step=state.ownerSetupStep||0,team=draft.team.filter(x=>x.enabled);return `${head(extras.ownerSetupComplete?'Fine-tune your shop.':'Make it your shop.','A few details. A smoother day for everyone.')}<div class="ops-setup-progress" aria-label="Step ${step+1} of 6">${setupStepLabels.map((s,i)=>`<span class="${i<=step?'active':''}"><i>${i<step?'✓':i+1}</i>${s}</span>`).join('')}</div><form id="owner-setup-form" class="panel ops-form" data-step="${step}"><small class="ops-eyebrow">STEP ${step+1} OF 6</small><h2>${['Start with your location.','The people behind the chairs.','Their craft. Their prices.','Make room for great work.','A clear agreement for every chair.','Ready for your next chapter.'][step]}</h2>${step===0?`<label class="field">Location<select name="location">${Object.entries(shops).map(([id,s])=>`<option value="${id}" ${draft.location===id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${setupInput('Location name','name',draft.name,'text','required maxlength="80"')}${setupInput('Shop address','address',draft.address,'text','required maxlength="220" autocomplete="street-address"')}`:step===1?draft.team.map(b=>`<div class="ops-team">${photo(barbers.find(x=>x.id===b.id))}<div>${setupInput('Display name',`name-${b.id}`,b.name,'text','required maxlength="80"')}<label class="check-row"><input type="checkbox" name="enabled-${b.id}" ${b.enabled?'checked':''}> Accept bookings</label></div></div>`).join(''):step===2?team.map(b=>`<fieldset class="ops-service-list"><legend>${esc(b.name)}</legend>${(draft.menus[b.id]||[]).map(s=>`<div class="ops-service-edit"><label class="check-row"><input type="checkbox" name="active-${b.id}-${s.id}" ${s.active!==false?'checked':''}> ${esc(s.name)}</label><div>${setupInput('Price ($)',`price-${b.id}-${s.id}`,s.price,'number','min="0" max="1000" step="0.01" required')}${setupInput('Minutes',`min-${b.id}-${s.id}`,s.min,'number','min="5" max="240" step="5" required')}</div></div>`).join('')}</fieldset>`).join('')+`<p class="muted">You can add and rename services later in Services & pricing.</p>`:step===3?`<p class="muted">Appointments must finish before closing. Blocked time and existing visits remain protected.</p>${draft.hours.map((hours,i)=>`<div class="ops-hours"><label class="check-row"><input type="checkbox" name="open-${i}" ${hours?'checked':''}> ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}</label><div>${setupInput('Opens',`start-${i}`,blockClock(hours?.[0]??540),'time','step="900" required')}${setupInput('Closes',`end-${i}`,blockClock(hours?.[1]??1140),'time','step="900" required')}</div></div>`).join('')}`:step===4?team.map(b=>{const t=draft.terms[b.id]||{mode:'split',barberPercent:60,amount:0,period:'week'};return `<fieldset class="ops-agreement"><legend>${esc(b.name)}</legend><label class="field">Agreement<select name="mode-${b.id}"><option value="split" ${t.mode==='split'?'selected':''}>Commission split</option><option value="rent" ${t.mode==='rent'?'selected':''}>Chair rental</option></select></label><div class="ops-split-controls" data-setup-split="${b.id}" ${t.mode==='rent'?'hidden':''}><label class="field">Barber share <output>${t.barberPercent}% barber / ${100-t.barberPercent}% shop</output><input type="range" name="share-${b.id}" min="0" max="100" step="1" value="${t.barberPercent}" aria-label="${esc(b.name)} commission percentage"></label><p class="muted">Tips stay with the barber.</p></div><div data-setup-rent="${b.id}" ${t.mode!=='rent'?'hidden':''}>${setupInput('Rental amount ($)',`rent-${b.id}`,t.amount||0,'number','min="0" max="100000" step="0.01"')}<label class="field">Frequency<select name="period-${b.id}">${['day','week','month'].map(p=>`<option value="${p}" ${t.period===p?'selected':''}>Per ${p}</option>`).join('')}</select></label></div></fieldset>`;}).join(''):`<div class="ops-review"><h3>${esc(draft.name)}</h3><p>${esc(draft.address)}</p><p>${team.length} barbers accepting appointments</p>${team.map(b=>{const t=draft.terms[b.id]||{mode:'split',barberPercent:60};return `<div class="line-item"><span>${esc(b.name)}<small>${draft.menus[b.id].filter(s=>s.active!==false).length} services</small></span><strong>${t.mode==='rent'?money(t.amount)+' / '+t.period:t.barberPercent+'% barber / '+(100-t.barberPercent)+'% shop'}</strong></div>`;}).join('')}<p class="notice">Your hours, services and chair agreements take effect when you finish setup. Existing appointments are kept.</p></div>`}<p class="ops-error" role="alert"></p><div class="ops-form-actions">${step?'<button type="button" class="btn secondary" data-ops="setup-back">Back</button>':''}<button class="btn" type="submit">${step===5?'Finish setup':step===4?'Review setup':'Continue'} ${icon('arrow')}</button></div><p class="ops-draft-note">${step===5?'Review before applying your settings.':'Your progress is saved as you continue.'}</p></form>`;}
function saveSetupStep(form){const step=Number(form.dataset.step),f=new FormData(form),draft=ownerSetupDraft();
 if(step===0){if(!shops[f.get('location')])throw Error('Choose a location.');if(!String(f.get('name')).trim()||!String(f.get('address')).trim())throw Error('Add your location name and address.');Object.assign(draft,{location:String(f.get('location')),name:String(f.get('name')).trim(),address:String(f.get('address')).trim()});}
 if(step===1){const team=draft.team.map(b=>({...b,name:String(f.get('name-'+b.id)).trim(),enabled:f.has('enabled-'+b.id)}));if(team.some(b=>!b.name)||!team.some(b=>b.enabled))throw Error('Add barber names and keep at least one barber available for bookings.');draft.team=team;}
 if(step===2){const menus=structuredClone(draft.menus);for(const b of draft.team.filter(x=>x.enabled)){for(const s of menus[b.id]){s.price=HFAppRules.requireNumber(f.get(`price-${b.id}-${s.id}`),0,1000,'Price');s.min=HFAppRules.requireNumber(f.get(`min-${b.id}-${s.id}`),5,240,'Duration');if(s.min%5)throw Error('Use service durations in 5-minute steps.');s.active=f.has(`active-${b.id}-${s.id}`);}if(!menus[b.id].some(s=>s.active))throw Error('Keep at least one service available for each active barber.');}draft.menus=menus;}
 if(step===3){const hours=draft.hours.map((_,i)=>{if(!f.has('open-'+i))return null;const start=HFOperations.minute(f.get('start-'+i)),end=HFOperations.minute(f.get('end-'+i));if(!Number.isInteger(start)||!Number.isInteger(end)||start%15||end%15||start>=end)throw Error('Choose opening and closing times in 15-minute steps.');return [start,end];});if(!hours.some(Boolean))throw Error('Keep at least one booking day open.');draft.hours=hours;}
 if(step===4){for(const b of draft.team.filter(x=>x.enabled)){const mode=String(f.get('mode-'+b.id));if(!['split','rent'].includes(mode))throw Error('Choose an agreement.');const percent=HFAppRules.requireNumber(f.get('share-'+b.id),0,100,'Barber share'),amount=mode==='rent'?HFAppRules.requireNumber(f.get('rent-'+b.id),0,100000,'Rent'):0;if(mode==='rent'&&amount===0)throw Error('Enter a rental amount greater than zero.');const period=String(f.get('period-'+b.id));if(!['day','week','month'].includes(period))throw Error('Choose a rental frequency.');draft.terms[b.id]={mode,barberPercent:percent,amount,period,collectionDay:1};}}
 if(step===5){extras.setupLocations={...extras.setupLocations,[draft.location]:{...shops[draft.location],name:draft.name,address:draft.address}};extras.shopHours={...extras.shopHours,[draft.location]:draft.hours};extras.barberProfiles=extras.barberProfiles||{};extras.staffBookingEnabled=extras.staffBookingEnabled||{};for(const b of draft.team){extras.barberProfiles[b.id]={...extras.barberProfiles[b.id],name:b.name};extras.staffBookingEnabled[b.id]=b.enabled;}extras.barberMenus=structuredClone(draft.menus);Object.assign(extras.chairTerms,draft.terms);extras.ownerSetupComplete={at:Date.now(),location:draft.location};extras.location=draft.location;state.scope=draft.location;applyOperations(operationSnapshot());save();go('home');toast('Your shop is ready. Settings applied.');return;}
 state.ownerSetupStep=step+1;save();render();window.scrollTo(0,0);
}
const renderExtraBeforeOperations=renderExtraView;renderExtraView=function(v){if(v==='ownerSetup')return ownerSetupPage();if(v==='notificationPreferences')return state.role==='Customer'?notificationPreferencesPage():head('Customer preferences.','Open this from your customer account.');return renderExtraBeforeOperations(v);};
const renderBeforeOperations=render;render=function(){renderBeforeOperations();
 if(state.role==='Owner HQ'&&state.view==='home')document.querySelector('.owner-summary')?.insertAdjacentHTML('beforebegin',`<button class="panel ops-setup-banner" data-ops="setup"><span class="ops-setup-icon">${icon(extras.ownerSetupComplete?'check':'settings')}</span><span><strong>${extras.ownerSetupComplete?'Your shop is set up':'Let’s make this your shop'}</strong><small>${extras.ownerSetupComplete?'Review locations, hours and chair agreements':'Location, barbers, services, hours and agreements'}</small></span>${icon('chevron')}</button>`);
 if(state.role==='Owner HQ'&&['more','settings'].includes(state.view))document.querySelector('#main .page-head')?.insertAdjacentHTML('afterend','<button class="btn secondary ops-setup-link" data-ops="setup">'+icon('settings')+' Shop setup</button>');
 if(state.role==='Customer'&&['cProfile','more'].includes(state.view))document.querySelector('#main')?.insertAdjacentHTML('beforeend','<button class="btn secondary full" data-view="notificationPreferences">'+icon('bell')+' Appointment notification preferences</button>');
 const manual=document.querySelector('#manual-booking');if(manual&&!manual.dataset.hoursFiltered){manual.dataset.hoursFiltered='true';updateManualTimes(manual);}if(manual&&!manual.querySelector('[name=appointmentTexts]'))manual.querySelector('button[type=submit],.btn')?.insertAdjacentHTML('beforebegin','<label class="check-row"><input type="checkbox" name="appointmentTexts"> Client agrees to appointment texts at this number</label>');
 if(state.view==='book'&&state.step===2){for(const el of document.querySelectorAll('[data-time]')){const error=schedulingError(state.barber,state.date,el.dataset.time,S().min,state.editing);el.disabled=!!error;if(error)el.title=error;}if(state.time&&schedulingError(state.barber,state.date,state.time,S().min,state.editing)){state.time='';document.querySelectorAll('[data-time].selected').forEach(el=>el.classList.remove('selected'));document.querySelector('[data-action=next]')?.setAttribute('disabled','');}}
};
document.addEventListener('click',e=>{const target=e.target.closest('[data-ops],[data-ops-visit]');if(!target)return;if(target.dataset.ops==='setup'&&state.role==='Owner HQ'){state.ownerSetupStep=extras.ownerSetupComplete?0:state.ownerSetupStep||0;go('ownerSetup');}if(target.dataset.ops==='setup-back'){state.ownerSetupStep=Math.max(0,(state.ownerSetupStep||0)-1);go('ownerSetup');}if(target.dataset.opsVisit){const b=bookings.find(b=>b.id===target.dataset.opsVisit);if(!b)return;if(isStaff())openAppointment(b.id);else go('bookings');}});
document.addEventListener('input',e=>{if(e.target.closest('#owner-setup-form')&&e.target.name.startsWith('share-'))e.target.parentElement.querySelector('output').textContent=`${e.target.value}% barber / ${100-Number(e.target.value)}% shop`;});
document.addEventListener('change',e=>{if(!e.target.closest('#owner-setup-form'))return;if(e.target.name.startsWith('mode-')){const id=e.target.name.slice(5);document.querySelector(`[data-setup-split="${id}"]`).hidden=e.target.value==='rent';document.querySelector(`[data-setup-rent="${id}"]`).hidden=e.target.value!=='rent';}if(e.target.name==='location'){const d=ownerSetupDraft(),id=e.target.value;d.location=id;d.name=shops[id].name;d.address=shopAddresses[id]||'';d.hours=structuredClone(extras.shopHours?.[id]||Array.from({length:7},(_,i)=>defaultShopHours(id,i)));document.querySelector('#owner-setup-form [name=name]').value=d.name;document.querySelector('#owner-setup-form [name=address]').value=d.address;}});
document.addEventListener('submit',e=>{const form=e.target;if(!['notification-preferences-form','owner-setup-form'].includes(form.id))return;e.preventDefault();try{if(form.id==='owner-setup-form'){if(state.role!=='Owner HQ')return;saveSetupStep(form);return;}const f=new FormData(form),phone=String(f.get('phone')||'').trim(),digits=phone.replace(/\D/g,'');if(f.has('sms')&&(!/^[+\d\s().-]+$/.test(phone)||digits.length<10||digits.length>15))throw Error('Add a valid mobile number to receive appointment texts.');extras.profile.phone=phone;extras.notificationPrefs=Object.fromEntries(['sms','confirmations','reminders','reschedules','cancellations'].map(k=>[k,f.has(k)]));extras.profile.reminders=f.has('reminders');save();toast('Notification preferences saved.');}catch(err){form.querySelector('[role=alert]').textContent=err.message;}},true);
applyOperations(operationSnapshot());
render();
function operationalHoursForm(){const schedule=extras.staffHours?.[activeBarberId()]||Array.from({length:7},(_,i)=>defaultShopHours(extras.location,i));return `${head('Your booking hours.','Choose when clients can book your chair.')}<form id="operational-hours-form" class="panel ops-form">${schedule.map((hours,i)=>`<div class="ops-hours"><label class="check-row"><input type="checkbox" name="open-${i}" ${hours?'checked':''}> ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}</label><div>${setupInput('Starts',`start-${i}`,blockClock(hours?.[0]??540),'time','step="900" required')}${setupInput('Finishes',`end-${i}`,blockClock(hours?.[1]??1140),'time','step="900" required')}</div></div>`).join('')}<p class="muted">Your hours are combined with shop hours. Existing appointments are kept; changes apply to new bookings and reschedules.</p><p class="ops-error" role="alert"></p><button class="btn full">Save booking hours</button></form><button class="btn secondary full" data-view="pBlock">${icon('clock')} Block a break or day off</button>`;}
availability=function(){return operationalHoursForm();};
document.addEventListener('submit',e=>{if(e.target.id!=='operational-hours-form')return;e.preventDefault();if(state.role!=='Barber Pro')return;try{const f=new FormData(e.target),hours=Array.from({length:7},(_,i)=>{if(!f.has('open-'+i))return null;const start=HFOperations.minute(f.get('start-'+i)),end=HFOperations.minute(f.get('end-'+i));if(!Number.isInteger(start)||!Number.isInteger(end)||start%15||end%15||start>=end)throw Error('Choose valid hours in 15-minute steps.');return [start,end];});extras.staffHours={...extras.staffHours,[activeBarberId()]:hours};save();toast('Booking hours updated.');}catch(err){e.target.querySelector('[role=alert]').textContent=err.message;}},true);

function updateManualTimes(form){const prior=form.elements.time.value,barber=form.elements.barber.value,date=form.elements.date.value,location=form.elements.location.value,hours=bookingHours(barber,date,location);form.elements.time.innerHTML=hours?times.filter(t=>minutes(t)>=hours[0]&&minutes(t)<hours[1]).map(t=>`<option ${t===prior?'selected':''}>${t}</option>`).join(''):'<option value="">Closed</option>';}
document.addEventListener('change',e=>{const form=e.target.closest('#manual-booking');if(form&&['barber','date','location'].includes(e.target.name))updateManualTimes(form);});
const openingStatusBeforeOperations=openStatus;openStatus=function(now=new Date()){const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Phoenix',year:'numeric',month:'2-digit',day:'2-digit'}).format(now),day=dateObj(date).getDay(),hours=extras.shopHours?.[extras.location]?.[day];if(hours===undefined)return openingStatusBeforeOperations(now);if(!hours)return {open:false,label:'Closed today'};const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(x=>[x.type,x.value])),minute=Number(p.hour)*60+Number(p.minute),open=minute>=hours[0]&&minute<hours[1];return {open,label:open?'Open until '+blockLabel(hours[1]):'Closed · Opens at '+blockLabel(hours[0])};};
if(window.visualViewport){let viewportFrame;const updateViewport=()=>{cancelAnimationFrame(viewportFrame);viewportFrame=requestAnimationFrame(()=>{const height=Math.round(visualViewport.height);document.documentElement.style.setProperty('--app-viewport-height',height+'px');document.body.dataset.keyboard=innerHeight-height>140&&!!document.activeElement?.matches('input,textarea')?'true':'false';});};visualViewport.addEventListener('resize',updateViewport);document.addEventListener('focusin',updateViewport);document.addEventListener('focusout',updateViewport);updateViewport();}

const dayBlockedBeforeOperations=dayBlocked;dayBlocked=function(date,barber=state.barber){return dayBlockedBeforeOperations(date,barber)||!bookingHours(barber,date)||extras.staffBookingEnabled?.[barber]===false;};

const openingLabelBeforeOperations=openingLabel;openingLabel=function(id){return extras.staffBookingEnabled?.[id]===false?'Not accepting bookings':openingLabelBeforeOperations(id);};
